# ── 事实守卫用的数字白名单 ──
# 【为什么对话版原来没有这一条】
# 牌局有 fact_guard（输出里的每个数字都必须在牌面数据里出现过），
# **对话版没有**——它的 guard 只查措辞，压根没看工具返回。
# 而稿子第 16 页承诺「试着让它说一个错的数字，看会不会被拦下」——
# **那一页演示的是牌局的能力，搬到对话版上会当场翻车。**
#
# 【为什么能补】
# 材料已经在了：stream_llm 每调一次工具就把
# (工具名, 参数, 返回值) 存进 calls。所以「这个数字工具说过吗」
# 是查得到的，不用猜。
_NUM_STOP = {1, 2, 3}          # 太小、太泛的数字不当证据（「三件事」）
# 这些词单独出现不算「在讲事实」，不用核数字。
# 反过来：**句子里出现这些词，就必须每个数字都核得住。**
_FACT_HINT = ("小时", "年", "月", "周", "分", "票", "%", "％", "率",
              "元", "人", "届", "就业", "薪酬", "起薪", "学费", "规模")
# 【中文数字必须认】
# 第一版 `_numbers` 只认 `\d+`。于是「临床医学要读**五**年」大摇大摆
# 走过去——而模型口语里写「五年」比写「5 年」还常见。
# **漏掉中文数字，等于这条守卫只挡了一半。**
_CN_NUM = {"一": 1, "两": 2, "二": 2, "三": 3, "四": 4, "五": 5,
           "六": 6, "七": 7, "八": 8, "九": 9, "十": 10,
           "百": 100, "千": 1000, "万": 10000}


def _numbers(text):
    """把一句话里的数字都抓出来（含小数、百分号、**中文数字**）。

    中文数字只做**逐字**取（「五」→5、「十」→10）。
    「十五」这种会被读成 10 和 5 两个数——不精确，但**方向是对的**：
    守卫只需要判断「这个数工具说过吗」，
    宁可多取几个去核（核不住就拦），也不漏。
    **这里漏一个数，编的数字就过去了。**
    """
    out = set()
    for m in re.finditer(r"\d+(?:\.\d+)?", text or ""):
        try:
            out.add(float(m.group(0)))
        except ValueError:
            pass
    for m in re.finditer(r"[一二两三四五六七八九十百千万]", text or ""):
        out.add(float(_CN_NUM[m.group(0)]))
    return out


def _all_numbers(calls):
    """工具返回里出现过的所有数字——**这是唯一的事实来源。**"""
    got = set()
    for rec in (calls or []):
        blob = rec[2] if len(rec) > 2 else ""
        for m in re.finditer(r"\d+(?:\.\d+)?", str(blob)):
            try:
                got.add(float(m.group(0)))
            except ValueError:
                pass
    return got


def fact_guard(text, calls, seen=None):
    """输出里的数字必须在工具返回里出现过。

    【和牌局的 fact_guard 同一条规矩】
    数字是唯一能被机械核对的东西。话说得再顺，**凭空多出一个
    「每周 60 小时」就是编的**——而用户看不出来。
    所以宁可把这一轮丢掉，也不让一个编出来的数字过去。

    【为什么还要 seen（跨轮累积的数字）】
    第一版只看**这一轮**的 calls。于是用户问完计算机、聊两句再回头问
    「刚才那个自驱几分」，模型复述 5 分——**明明是它自己查过的数，
    守卫却判成编的，把整句话吞掉。**
    误拦比漏拦更常见，而且更难看：用户会觉得它莫名其妙不说话。
    所以把「这一轮查过的」和「前面查过的」并起来。

    【为什么要把维度名整段遮掉】
    「七维」这个词里有个「七」。模型说「计算机的**七维**里自驱要求是 4 分」
    ——**这是一句完全正确的话**，而「七」不在任何工具返回里，
    于是被当成编的数字拦下。
    「七维」「7 维」是这产品的口头禅，会天天撞。
    所以先把维度名（DIM_NAMES / DIM_SHORT 及其中的数字说法）整段换成空格，
    再核剩下的数——**遮的是维度名本身，不是放宽阈值。**
    """
    t = text or ""
    if not any(h in t for h in _FACT_HINT):
        return True, None
    # 遮掉维度名的说法（「七维」「7 维」「七项」「7 项」「七个维度」）
    t = re.sub(r"[七7]\s*[维项个]", " ", t)
    t = re.sub(r"七个维度", " ", t)
    for _n in DIM_NAMES:
        t = t.replace(_n, " ")
    for _n in DIM_SHORT:
        t = t.replace(_n, " ")

    allowed = _all_numbers(calls) | set(seen or ())
    for n in _numbers(t):
        if n in _NUM_STOP:
            continue
        # 数字在返回里出现过（允许 1% 的浮点误差）
        if any(abs(n - a) <= max(0.01, abs(a) * 0.01) for a in allowed):
            continue
        return False, f"它说了一个工具没给过的数字（{n:g}）——这是编的。"
    return True, None



