# ==================================================================
# 没填 key 时的「翻卡」：认人名、认口语、认打错的字
# ==================================================================
# 【为什么单独写这一段，而不是接着用那一行 `next(...)`】
# 原来那行是：
#     hit = next((mm for nm, mm in BY_NAME.items() if nm in low), None)
# 它要求**专业全名完整出现**在输入里。于是：
#   「软件工程」→ 出卡（能用）
#   「计算机」  → 没有这个专业名，接不住
#   「软工」    → 接不住
#   「我想学医」→ 接不住
# 而输入框的提示语写的是「说个专业名、问问区别，或者随便说点什么」——
# **提示语承诺的比这条规则能给的宽得多**，人一打就撞墙。
# 这不是 bug，是这条路径太薄。所以这里补三层：
#   ① 全名包含（原来那层，快的先走）
#   ② 专业类名 → 把这一类里能翻的牌列出来（「计算机类」是一种问法）
#   ③ 二元组相似 → 认简称、认口语、认打错的字，并给出近似候选
#
# 【为什么要去标点虚词】
# 「我想学医」里的「我想学」对匹配毫无用处，留着只会稀释相似度。
# 这和工具层 `_iv_norm` 是同一个道理，但**那套在工具层里，
# 而翻卡模式根本没有工具层**（它连模型都没接），所以这里必须自带一份。
# 【为什么这里不去跟 `_iv_norm` 共用】
# 共用要先把工具层整体引入，而没填 key 时引入工具层等于引入一整套
# 用不上的评分逻辑。宁可写一份小的、命名不同的（`_card_*`），
# 也不要把两条不相干的路径焊在一起。
_CARD_DROP = ("我自己", "我们", "他们", "这个", "那个", "什么", "怎么",
              "的话", "感觉", "觉得", "应该", "可能", "就是", "然后",
              "其实", "反正", "不过", "但是", "而且", "因为", "所以",
              "我想学", "我想", "我要学", "我要", "想学", "想读", "想报",
              "学什么", "读什么", "有没有", "了解", "介绍一下", "介绍",
              "怎么样", "好不好", "请问", "帮我", "看看", "哪个")
_CARD_PUNCT = "，。！？、；：""''（）《》〈〉【】…—～·,.!?;:\"'()[]{}<>/\\|~@#$%^&*_-+=`"


def _card_norm(s):
    """归一化：小写、去标点、去那些对判断没用的字。"""
    low = str(s or "").strip().lower()
    for p in _CARD_PUNCT:
        low = low.replace(p, "")
    for w in _CARD_DROP:
        low = low.replace(w, "")
    return low


def _card_bigrams(s):
    """字符二元组。中文短文本比相似度，这是稳的做法。

    【为什么不用单字重合】分母取 min 的话，输入越短越容易满分——
    打「医学」两个字就可能压过所有长名字。
    （同样的道理写在工具层 `_iv_bigrams` 的注释里，那套是给访谈答话用的。）
    """
    s = _card_norm(s)
    if len(s) < 2:
        return set(s)
    return set(s[i:i + 2] for i in range(len(s) - 1))


# 专业类名 → 这一类里**能翻出牌**的专业名
#
# 【这里原来写错了键名】我第一版写的是 `_m.get("cls")`——那是
# `_cards_core.py` 里 `summary_data()` **输出**用的短名，
# 而专业记录**存**的是中文键 `专业类`。于是这张表是空的（0 条），
# 症状是「计算机类」这种问法悄悄退化成模糊匹配。
# 这类「键和值的角色搞反」的错，症状是**静默查不到**，最难查。
_CARD_OF_CLASS = {}
for _m in MAJORS:
    _c = (_m.get("专业类") or "").strip()
    if _c:
        _CARD_OF_CLASS.setdefault(_c, []).append(_m["n"])
# 类名本身多半带「类」字，这里再补一个不带「类」的键，
# 这样「计算机类」和「计算机」两种打法都能一次命中。
for _c in list(_CARD_OF_CLASS):
    _CARD_OF_CLASS.setdefault(_c[:-1] if _c.endswith("类") else _c,
                              _CARD_OF_CLASS[_c])
# 类内按牌数从多到少，先给牌多的那几类
for _c in _CARD_OF_CLASS:
    _CARD_OF_CLASS[_c] = sorted(set(_CARD_OF_CLASS[_c]),
                                key=lambda n: -len(n))

# 口语里最常出现的说法 → 官方专业类名（一张别名可以指向**多个**类）
#
# 【为什么要有这一张】
# 「我想学医」这句话，库里明明有临床医学、中医学、动物医学，
# 原来的匹配却接不住：归一后只剩一个字「医」，对不上任何专业全名，
# 也凑不出二元组。**这不是严谨，是没用。**
#
# 【第一版错在哪】
# 我写了 `"医学": "医学类"`，可**库里根本没有叫「医学类」的专业类**——
# 医学被拆在临床医学类、中医学类、口腔医学类、公共卫生与预防医学类、
# 医学技术类、护理学类六个类里。名字猜错了，整张表就静默失效
# （`if _v in _CARD_OF_CLASS` 把它跳过了，一声不响）。
# 所以这张表**必须对着真实类名写**，下面加断言，写错就当场报出来。
#
# 【为什么要克制】
# 只收**方向明确、不会误导**的说法。
# 「跟人打交道」「稳定一点」这种一概不收——
# 那样猜出来的方向，用户会当成是我在替他定。
# 而且别名只指向**类**（多张牌），不指向某一个专业：
# 方向给到，具体哪张他自己看，**不是我替他挑一张**。
_CARD_ALIAS = {
    # 医学：六个类都算
    "医": ["临床医学类", "中医学类", "口腔医学类",
           "公共卫生与预防医学类", "医学技术类", "护理学类"],
    "学医": ["临床医学类", "中医学类", "口腔医学类",
             "公共卫生与预防医学类", "医学技术类", "护理学类"],
    "医学": ["临床医学类", "中医学类", "口腔医学类",
             "公共卫生与预防医学类", "医学技术类", "护理学类"],
    "当医生": ["临床医学类"], "医生": ["临床医学类"],
    "计算机": ["计算机类"], "电脑": ["计算机类"],
    "编程": ["计算机类"], "写代码": ["计算机类"], "程序员": ["计算机类"],
    "人工智能": ["计算机类", "自动化类"],
    "经济": ["经济学类", "财政学类", "金融学类", "经济与贸易类"],
    "金融": ["金融学类"], "钱": ["金融学类"],
    # 【「法律」不能映射到法学类】库里有一个专业名叫「法律(非法学)」，
    # 用户打「法律」时**会先被专业全名那一层命中**，根本轮不到别名。
    # 这是对的——他打的确实是一个专业名的前缀。别名只补「律师」这类说法。
    "律师": ["法学类"], "当律师": ["法学类"], "打官司": ["法学类"],
    "老师": ["教育学类"], "当老师": ["教育学类"], "师范": ["教育学类"],
    "教书": ["教育学类"],
    "画画": ["美术学类", "设计学类"], "美术": ["美术学类"],
    "音乐": ["音乐与舞蹈学类"], "舞蹈": ["音乐与舞蹈学类"],
    "中文": ["中国语言文学类"], "写作": ["中国语言文学类"],
    "外语": ["外国语言文学类"], "英语": ["外国语言文学类"],
    "新闻": ["新闻传播学类"], "媒体": ["新闻传播学类"],
    "历史": ["历史学类"], "考古": ["历史学类"],
    "哲学": ["哲学类"],
    "数学": ["数学类"], "物理": ["物理学类"], "化学": ["化学类"],
    "生物": ["生物科学类"], "心理": ["心理学类"],
    "土木": ["土木类"], "建筑": ["建筑类"],
    "机械": ["机械类"], "电子": ["电子信息类"],
    "电气": ["电气类"], "自动化": ["自动化类"],
    "会计": ["工商管理类"], "管理": ["工商管理类",
                                     "管理科学与工程类"],
    "旅游": ["旅游管理类"], "设计": ["设计学类"],
    "农": ["植物生产类", "林学类", "水产类"],
    "环境": ["环境科学与工程类"], "食品": ["食品科学与工程类"],
    "航空": ["航空航天类"], "航天": ["航空航天类"],
}
# 【写错类名就当场报出来】第一版就是错在这里、还一声不响。
for _k, _vs in _CARD_ALIAS.items():
    for _v in _vs:
        assert _v in _CARD_OF_CLASS, f"别名「{_k}」指向了不存在的专业类「{_v}」"
    _names = []
    for _v in _vs:
        _names += _CARD_OF_CLASS[_v]
    # 去掉重复，按牌数（类内已排好）保留先出现的
    _seen, _uniq = set(), []
    for _n in _names:
        if _n not in _seen:
            _seen.add(_n)
            _uniq.append(_n)
    _CARD_OF_CLASS[_k] = _uniq


def _card_ordered(q, name):
    """q 的字符能不能在 name 里**按顺序**找到。找不到给 0。

    【为什么二元组不够，非得再加这一层】
    「软工」→「软件工程」：二元组是 {软工}，而「软件工程」里是
    {软件, 件工, 工程}——**一个都不重合，分数 0**。
    可这是全国通用的简称，必须认。
    「学医」→「临床医学」：只有一个字，二元组根本产生不出来。
    有序匹配两层都能救，而且它比二元组更贴合中文的省写习惯。
    """
    it = iter(name)
    for ch in q:
        if ch not in it:
            return 0.0
    return 1.0


def _card_score(q, name):
    """两段拼起来的相似度：二元组覆盖 + 有序字符匹配。

    【这两个是怎么选出来的】
    我拿 22 条**带标准答案**的真人输入（该给卡的、该只给候选的、
    该接不住的各一批）把四种算法 × 八个阈值全跑了一遍：
      · 二元组 Dice            最好也只有 3 处错（「软工」「学医」全漏）
      · 二元组覆盖（取短边）   2 处错
      · 覆盖 + 有序字符        阈值 0.50~0.65 之间**零错**
    所以用这一套，阈值 0.55（区间正中，两头都留了余量）。
    【最关键的一条】「打游戏」不能撞上「戏剧影视文学」，
    「我不想学数学」不能撞上「数学与应用数学」——
    前者是靠有序匹配的**连续性**压掉的，后者是靠阈值压掉的。
    """
    a, b = _card_bigrams(q), _card_bigrams(name)
    bg = 0.0
    if a and b:
        bg = len(a & b) / min(len(a), len(b))
    od = _card_ordered(q, name)
    if not od:
        return bg
    # 有序匹配到了，但还要看贴不贴：连着当然比跳着强
    return max(bg, od * (1.0 if q in name else 0.75))


# 判定阈值。区间 0.50~0.65 都是零错，取中间。
_CARD_HIT_MIN = 0.55
_CARD_NEAR_MIN = 0.40


def card_hits(text, k=4):
    """认一段输入，返回 (要翻的牌, 近似候选, 命中的类名)。

    三种命中按可靠性排序：**全名 > 类名 > 相似**。
    全名和类名是「他确实说中了」，相似只是「他没说清，我猜的」——
    调用方必须把这两种在话里区分开，不能都当成「你说的是这个」。
    """
    low = _card_norm(text)
    if not low:
        return [], [], None

    # ① 全名包含。长的优先，免得「计算机」把「计算机科学与技术」盖掉。
    exact = [m for nm, m in BY_NAME.items() if _card_norm(nm) in low]
    if exact:
        exact.sort(key=lambda m: -len(m.get("n") or ""))
        return exact[:k], [], None

    # ② 类名。他说「计算机类」时，把这一类里能翻的牌列出来。
    if low in _CARD_OF_CLASS:
        hits = [BY_NAME[n] for n in _CARD_OF_CLASS[low] if n in BY_NAME]
        return hits[:k], [], low

    # ③ 相似。简称、口语、打错字走这条。
    if len(low) < 2:
        return [], [], None
    scored = sorted(((_card_score(low, _card_norm(nm)), m)
                     for nm, m in BY_NAME.items()), key=lambda x: -x[0])
    best = scored[0][0] if scored else 0.0
    if best >= _CARD_HIT_MIN:
        # 同一个分数可能有几个（比如「计算机」命中好几种计算类），
        # 取最高的那几个一起给，让他自己认。
        top = [m for s, m in scored if s >= best - 0.02][:k]
        return top, [], None
    if best >= _CARD_NEAR_MIN:
        return [], [m for _s, m in scored[:k]], None
    return [], [], None


def keyless_reply(text):
    """没填 key 时，给一句人话 + 要翻的牌。

    【为什么话要分三种】
    因为「我确实认出了你说的那个」和「我猜的」是两回事。
    猜的时候**必须把猜的那个名字说出来**——不然他以为自己打对了，
    而屏幕上那张卡说的是别的专业，这比接不住更糟。
    """
    hits, near, cls = card_hits(text)
    if cls:
        # 【说一句「还有多少张」】`card_hits` 只给前 `k` 张（4 张）。
        # 「画画」落在美术学类上，这一类有 5 个专业，用户看到的却是 4 张——
        # **不告诉他还被截断了，他会以为这一类就只有这 4 个。**
        # 所以报个数，并且给一条继续往下走的路（打名字）。
        _all = _CARD_OF_CLASS.get(cls) or []
        line = f"{cls}底下的，我这儿能翻出来这几张："
        if len(_all) > len(hits):
            line = (f"{cls}底下我这儿有 **{len(_all)}** 张，"
                    f"先给你这几张：")
        return line, hits
    if hits:
        # 【含糊命中要说清】他打了半句话，命中是靠里面几个字。
        # 让他知道翻的是哪一张，否则他没法纠正。
        if len(hits) > 1 or _card_norm(hits[0]["n"]) != _card_norm(text):
            return f"我按「{hits[0]['n']}」翻的。", hits
        return "给你看。", hits
    if near:
        return ("相近的这几张你先看看——"
                + "、".join(m["n"] for m in near[:3])), near[:3]
    return ("牌堆里没有叫这个的。官方目录里 **883** 个专业，"
            "我这儿做成卡的只有一部分。"
            "**你直接打专业名试试**，比如「软件工程」。"), []


