# -*- coding: utf-8 -*-
# --- 以下原为 _tools_core 的文件级说明，改成注释以免被渲染 ---
#
# 【为什么要做成工具，而不是把数据塞进 prompt】
# 176 个专业 + 97 个职业族 + 官方四维满意度 + 845 条评级，
# 全塞进 prompt 不现实（几十万字符），而且模型会**记错、会编**。
#
# 做成工具之后有一条硬规矩：
#     **模型对专业说的每一句事实，都必须来自某次工具调用的返回值。**
# 它不能凭记忆说「计算机专业就业很好」——得先查，查到什么说什么，
# 查不到就说查不到。这条规矩是把「陪你聊」和「一本正经胡说」分开的东西。
#
# 【产品底线，写在工具层而不是提示词里】
# script.py 原文那三条，这里用代码而不是嘱咐来保证：
#   1. 现实条件（家里条件/地域/成绩）只能影响可行性和时间表，
#      不能影响「你这个人适合什么」→ see_record_self / see_record_reality 分开
#   2. 低证据 ≠ 低能力 → 没数据时工具返回「没有」，不许返回「低」
#   3. 不给唯一「最佳答案」→ 没有 recommend 工具，只有 lookup

import importlib as _importlib

DIM_KEYS = ["认知负荷", "记忆量", "细节分辨", "动手要求",
            "自驱要求", "挫折耐受", "慢反馈耐受"]

# ── 共用核心里的东西：两种运行方式都要能用 ──
# 这个文件有两种活法：
#   ① 被 `_assemble_agent2.py` 内联进 `志业镜.py`——
#      那时 `_mirror_core.py` 的内容也内联在同一个命名空间里，
#      `OPTIONS` / `ASK` 直接就能看见；
#   ② 被单独 import（测试、单跑）——那时什么都没有。
#
# 【为什么必须显式兜住】
# 第一版裸用 `OPTIONS[dim]`，于是**单独跑就 NameError**。
# 内联兜住了它，所以应用里看不出问题——
# **一个只在「另一种跑法」下才炸的错，最难发现，也最容易在演示外的地方炸。**
# 这里显式取一次：取得到就用，取不到留空，让代码自己判断。
try:
    _mc = _importlib.import_module("_mirror_core")
    ASK = getattr(_mc, "ASK", [])
    OPTIONS = getattr(_mc, "OPTIONS", {})
    DIM_SHORT = getattr(_mc, "DIM_SHORT", {})
    Q_OF = getattr(_mc, "Q_OF", {})
except Exception:                       # noqa: BLE001
    # 内联运行时走这里：宿主命名空间里已经有了，用 globals() 兜
    ASK = globals().get("ASK", [])
    OPTIONS = globals().get("OPTIONS", {})
    DIM_SHORT = globals().get("DIM_SHORT", {})
    Q_OF = globals().get("Q_OF", {})

