def card_html(m):
    """把专业画成一张卡。**只给第一眼该看的东西。**

    【这一版改成用共享的 `_cards_core.py`，不再各写一份】
    原来的简版卡有两个真问题：
      1. **完全不显示代价**——而「这条路要花多久、好不好回头」
         是用户最想知道的之一；
      2. 完全不提「模板值」——88 个专业的代价数字是按专业类常见情况
         填的，不标出来就是**拿估计冒充准数**。
    这两件事在牌局那边的卡片里是处理过的，但代码写在 `_majors_src.py` 里，
    对话版拿不到。现在两边共用 `_cards_core.py`：
    紧凑视图靠 `summary_data()`，想看全的展开走 `render_card()`。

    【为什么不禁着按「读报告」来写】
    聊天是往下滚的，一张牌铺六个块就把刚才说的话顶出屏幕了。
    用户要的是「就像在和你说话，纸牌是穿插的操作」——**纸牌是穿插的**。
    """
    d = summary_data(m, DIM_NAMES, DIM_PLAIN)
    rows = []
    if d["dims_hi"]:
        rows.append("<div class='mk'><b>它对人的要求</b><br>"
                    + "<br>".join(f"· {plain} <code>{v}/5</code>"
                                  for _n, plain, v in d["dims_hi"])
                    + "".join(f"<br><span class='dim'>· {plain} "
                              f"<code>{v}/5</code></span>"
                              for _n, plain, v in d["dims_lo"])
                    + "</div>")
    else:
        rows.append("<div class='mk dim'>这个专业还没有「需求画像」"
                    "（161 个里 94 个有）</div>")
    # 代价：**模板值必须当场标出来**
    if d["cost"]:
        _tag = ("　<span class='dim'>⚠ 这几个数是模板值，"
                "按这个专业类常见情况填的，不是实测</span>"
                if d["cost_templated"] else
                (f"　<span class='dim'>等级 {_esc(d['cost_tier'])}</span>"
                 if d["cost_tier"] else ""))
        rows.append(f"<div class='mg'><b>要花多少</b><br>{d['cost']}"
                    f"{_tag}</div>")
    return f"""<div class="mcard">
  <div class="mt">{_esc(d['icon'])} {_esc(d['name'])}</div>
  <div class="ms">{_esc(d['gate'])} · {_esc(d['cls'])} · \
{_esc(d['degree'])} · {_esc(d['years'])} 年</div>
  <div class="mh">{_esc(d['hook'])}</div>
  <div class="mg"><b>学什么</b><br>{_esc(d['core']) or '—'}</div>
  {''.join(rows)}
  {f"<div class='mg'><b>谁适合</b><br>{_esc(d['suits'])}</div>" if d['suits'] else ''}
  {f"<div class='ma'>这个下午就能试：{_esc(d['act'])}</div>" if d['act'] else ''}
  {f"<div class='mg'><b>出来能干什么</b><br>" + '　'.join(_esc(x) for x in d['exits']) + "</div>" if d['exits'] else ''}
</div>"""


def sources_block(m):
    """逐条标出处。**这是「数据以官方源为准并逐条标注出处」那句话的落地。**

    【为什么不能只在卡片底下写一句「来源：见侧栏」】
    一张卡上的信息来自**四个不同来源，可信度差得很远**：
      · 分类/代码/学位  → 教育部官方目录（硬事实）
      · 就业方向        → 学职平台官方登记（政府平台）
      · 四维满意度      → 学信网实名投票（**学生自评，方向性**）
      · 三维星级/推荐指数 → 两位老师的材料（**个人判断，不是数据**）
      · 需求画像 7 维   → 6 个访谈核实 / 88 个公开资料推
      · 代价数字        → 88 个是模板值
    混成一句「来源：多个渠道」就等于没说。所以逐条摊开。

    【另一个刻意的设计】
    「教育部目录覆盖」那一行不是写死的清单，是**从数据算的**：
    用 class2gate（专业类码→门类）反查我这 163 个专业属于哪些**官方在册**
    的专业类。这样以后加专业它会自己更新，不会变成一张过期的表。
    """
    g = MAJOR_DATA
    c2g = g.get("class2gate") or {}
    off_classes = g.get("official_classes") or {}
    cl = m.get("专业类") or ""
    cls_code = next((c for c, n in off_classes.items() if n == cl), None)
    gate_ok = bool(cls_code and c2g.get(cls_code))
    sat = m.get("chsi_sat") or {}
    rows = []

    if gate_ok:
        rows.append(("分类·代码·学位", "官方", "教育部《本科专业目录》"
                     f"（{m.get('门类')} · {m.get('专业类')}"
                     + (f" · {m['code']}" if m.get("code") else "") + "）"))
    else:
        rows.append(("分类", "待核", "不在官方目录里对得上，"
                     "这一项我没核实"))

    if m.get("chsi_jyfx"):
        rows.append(("就业方向", "官方", "学职平台 xz.chsi.com.cn"
                     "（教育部学生服务与素质发展中心）"))
    if sat:
        n = sat.get("total") or 0
        soft = "票少，仅供参考" if n < 300 else ""
        rows.append(("四维满意度", "官方·学生自评",
                     "学信网阳光高考专业库，在读学生实名投票"
                     f"（{n:,} 票{('，' + soft) if soft else ''}）"))
    if m.get("chsi_xsgm"):
        rows.append(("在校生规模", "官方", "同上"))
    if m.get("rating"):
        rows.append(("三维星级", "个人判断",
                     (m["rating"].get("src") or "") + "（**不是数据**）"))
    if m.get("rec_index"):
        rows.append(("推荐指数", "个人判断",
                     (m["rec_index"].get("src") or "") + "（**不是数据**）"))
    if m.get("dims"):
        t = m.get("dims_tier")
        rows.append(("7 维需求画像",
                     "访谈核实" if t == "C1" else "公开资料推",
                     "志业镜原库" + ("（逐个访谈核实过）" if t == "C1"
                                 else "（**没有逐一核实**）")))
    if m.get("cost_hours"):
        rows.append(("代价数字",
                     "模板值" if m.get("cost_templated") else "访谈核实",
                     "**同批数挤在同一个值上，别当准数**"
                     if m.get("cost_templated") else "逐个访谈核实"))
    rows.append(("学什么 / 代价 / 谁适合", "整理",
                 m.get("src") or "公开资料整理"))

    if not rows:
        return
    st.markdown("**这一张卡，每条信息哪来的**")
    for what, kind, src in rows:
        st.markdown(f"- `{what}`　**{kind}**　—— {src}")


def render_assistant(text, shown=()):
    """把模型的话画出来，遇到 [[CARD:x]] 就插一张卡。

    【为什么要这个标记】
    卡片是「它拿给你看的东西」，得由它决定插在哪一句话后面。
    所以让它自己写 `[[CARD:专业名]]`，我按这个切开渲染。
    没有这个标记它就只能干说，那又变回聊天机器人了。
    """
    import re
    parts = re.split(r"\[\[CARD:\s*([^\]]+?)\s*\]\]", text)
    for i, part in enumerate(parts):
        if i % 2 == 0:
            if part.strip():
                st.markdown(part.strip())
        else:
            m = BY_NAME.get(part)
            if m:
                st.markdown(card_html(m), unsafe_allow_html=True)
                # 【牌局那一整套现在都在这里，但收着】
                # 聊天流里塞六个块会把刚才说的话顶出屏幕，所以要紧凑版；
                # 可牌局那边「逐条标出处」「出口分官方/整理」这些
                # **不是装饰，是产品承诺**（数据以官方源为准并逐条标注出处）。
                # 所以给一个展开：想查的人一眼能找到，不想看的人不被打断。
                with st.expander("看全一点（代价、出口、每一句的出处）"):
                    render_card(st, m, DIM_NAMES, DIM_PLAIN,
                                occ_by_name=OCC_BY_NAME,
                                occ_alias=OCC_ALIAS,
                                not_jobs=NOT_JOBS,
                                occ_nodetail=OCC_NODETAIL,
                                sources=sources_block(m))
            else:
                # 模型编了一个不存在的专业名 —— 不画卡，如实说
                st.warning(f"它想给你看「{part}」，但库里没有这个专业。"
                           f"（这种时候不要信它的描述。）")


def _client(key):
    """建 OpenAI 客户端（DeepSeek 兼容 OpenAI 协议）。

    不带 key 就返回 None —— **调用方必须自己处理 None，不许假装能聊。**
    """
    if not key:
        return None
    try:
        from openai import OpenAI
    except ImportError:
        return None
    return OpenAI(api_key=key, base_url=BASE_URL)


def stream_llm(client, messages, ctx, max_rounds=6):
    """跑一轮对话，允许模型来回调工具。

    返回 (最终文本, 本轮工具调用轨迹, 出错信息)
    """
    calls = []
    msgs = list(messages)
    for _ in range(max_rounds):
        try:
            resp = client.chat.completions.create(
                model=MODEL, messages=msgs,
                tools=tool_specs(), tool_choice="auto",
                temperature=0.8, max_tokens=1200)
        except Exception as e:
            return None, calls, f"{type(e).__name__}: {e}"
        msg = resp.choices[0].message
        if not getattr(msg, "tool_calls", None):
            return (msg.content or ""), calls, None
        msgs.append({"role": "assistant",
                     "content": msg.content or "",
                     "tool_calls": [tc.model_dump() for tc in msg.tool_calls]})
        for tc in msg.tool_calls:
            try:
                args = json.loads(tc.function.arguments or "{}")
            except Exception:
                args = {}
            out = run_tool(tc.function.name, args, ctx)
            calls.append((tc.function.name, args,
                          str(out)[:160]))
            # 【把这一轮看到的数字累进 ctx】
            # fact_guard 只看「这一轮查过的」会把**上一轮真查过的数**
            # 判成编的（用户回头问「刚才那个几分」就会撞上），
            # 整句话被吞掉。所以这里跨轮累积。
            ctx.setdefault("seen_nums", set()).update(
                _numbers(json.dumps(out, ensure_ascii=False, default=str)))
            msgs.append({"role": "tool", "tool_call_id": tc.id,
                         "content": json.dumps(out, ensure_ascii=False,
                                               default=str)[:12000]})
    return None, calls, "它连着调了太多工具，我把它叫停了。"


def guard(text, calls, seen=None):
    """后置守卫：模型违反产品底线就丢掉这一轮。

    从 script.py 的 polish() 搬过来。原文注释：
    「宁可不要润色，也不能让立场被悄悄改坏。」

    【两道关，顺序有讲究】
      ① 措辞关（BANNED）——「建议你选」这种，**先查**，
         因为它一眼就能判，不用看工具返回。
      ② 事实关（fact_guard）——数字必须来自工具返回。
         这道关以前**只在牌局里有**，对话版漏了；
         而稿子上承诺的现场演示正好是这一条。
    """
    bad = [w for w in BANNED if w in (text or "")]
    if bad:
        # 【这是内部诊断串，不会印给用户】
        # `why` 在调用处只当布尔用（`if why:`），一个字都不上屏。
        # 但措辞照样收干净：留着一句「这是替你做决定，越线了」，
        # 下一个人很容易顺手把它 st.warning 出去——
        # 而用户明确说过「不需要你管做不做决定」。
        return None, f"措辞关拦下：{'、'.join(bad)}"
    ok, why = fact_guard(text, calls, seen)
    if not ok:
        return None, why
    return text, None


# ==================================================================
# 撞到「不替你选」那道墙的时候，**同一秒把内容补上**
# ==================================================================
# 【为什么要有这一段】
# 用户原话：「那个所谓的不帮你做选择的越界问题很容易，使聊天变死，
# 我希望你能在避免引导做决定的同时，**积极开拓出新的内容**」。
#
# 改之前，撞墙的处理是印一句
# 「这句我不替你说……要不要我陪你把这两条路摆开看看？」
# ——它是客气话，但**球被丢回给用户了**：他没得到任何东西，
# 还得自己想问什么。这就是「聊天变死」的机制。
#
# 现在改成：拦掉那一句的同时，把**同一批事实换个角度**端上去。
# 换的角度全是中性的——摊开、不评判、不排序，所以
# 「不替他做决定」这条线一点没松。
#
# 【为什么角度是抽签而不是固定】
# 固定同一套角度，多撞几次墙就变成新的复读机——
# 而用户抱怨的正是重复。
#
# 【这些数字从哪来】
# 全部来自 `summary_data()` / `card_data()`，也就是**牌上本来就印着**的
# 那几个数（要花多少、它要什么、学什么）。这里不新增任何事实，
# 所以不需要再过一遍事实关。

_ANGLE_TAIL = [
    "**换个角度**：这两条里，**哪一条你已经知道是自己不要的？**"
    "——「不要什么」比「要什么」准得多。",
    "**再往下一层**：去打听一下**真在干这行的人，一整天在干什么**。"
    "专业介绍里那套和实际干活差得远。",
    "**反过来看**：这条路**容不容易回头**？"
    "想换的时候换不动，比选错更麻烦。",
    "**不用等毕业就能试的**：挑一个你这周就能做的小东西做完。"
    "做完你会知道一件真的，比现在想十天都有用。",
]
# 【撞墙计数器】见 `_angle_shift()` 里的说明：
# 不能用 session_state 当种子，刷新后它就归零了。
_WALL_N = 0


def _angle_shift(text):
    """从被拦掉的那句话里挖出「它想推荐谁」，换成中性内容端上去。

    返回 markdown 文本；**挖不出东西就返回 None**，
    让调用方退回到不会撒谎的说法。
    """
    # ① 它想推荐哪个专业
    try:
        hits = [m for nm, m in BY_NAME.items() if nm in (text or "")]
    except NameError:
        hits = []
    # 长名字排在前面，免得「计算机」把「计算机科学与技术」盖掉
    hits.sort(key=lambda m: -len(m.get("n") or ""))
    seen, uniq = set(), []
    for m in hits:
        if m["n"] not in seen:
            seen.add(m["n"])
            uniq.append(m)
    if not uniq:
        return None

    out = ["先把东西放这儿："]
    try:
        for m in uniq[:2]:
            d = summary_data(m, DIM_NAMES, DIM_PLAIN)
            bits = []
            if d["dims_hi"]:
                bits.append("、".join(f"{p} {v}/5"
                                      for _n, p, v in d["dims_hi"]))
            if d["cost"]:
                # 【模板值必须标出来】不标就是拿估计冒充准数
                bits.append(d["cost"].replace("**", "")
                            + ("（模板值，不是实测）"
                               if d["cost_templated"] else ""))
            if d["core"]:
                bits.append(d["core"].replace("**", ""))
            if bits:
                out.append(f"- **{m['n']}**　" + "；".join(bits))
            # 【牌不插进聊天流】卡片是穿插的操作，一次一张，
            # 这里是「撞墙之后的补料」，塞卡会喧宾夺主。
            # 所以只给事实，不提卡片。
    except NameError:
        return None
    # 【角度为什么要轮着换，以及为什么不能用 session_state 当种子】
    # 固定同一句，多撞几次墙就变成新的复读机——
    # 而用户抱怨的正是重复。
    # 我第一版拿 `len(st.session_state.msgs)` 当种子。
    # **那是错的**：那段在 streamlit 里只有**每一次 rerun 都取到同一个值**
    # 才会动，而刷新之后它就是 0——等于永远第一句。
    # 所以改成一个**模块级计数器**：它活在服务进程里，
    # 每撞一次墙就往前走一格，跟会话状态没关系。
    global _WALL_N
    _WALL_N += 1
    out.append(_ANGLE_TAIL[_WALL_N % len(_ANGLE_TAIL)])
    return "\n\n".join(out)


