def new_ctx():
    return {"majors": MAJORS, "by_name": BY_NAME,
            "occ_by_name": OCC_BY_NAME, "occ_majors_stat": OCC_MAJORS_STAT,
            # 出处核对需要官方目录对照表，**显式传进去**，
            # 免得 tools 层靠全局变量拿到一个它不该依赖的东西
            "major_data": MAJOR_DATA,
            "self_notes": [], "reality_notes": [], "impressions": [],
            "shown": [], "trace": []}


def mirror_fn_factory(ctx):
    def f():
        col = [BY_NAME[x] for x in ctx.get("collected", []) if x in BY_NAME]
        rej = [(BY_NAME[x], rs) for x, rs in ctx.get("rejected", [])
               if x in BY_NAME]
        return read_mirror(col, rej)
    return f


if "ctx" not in st.session_state:
    st.session_state.ctx = new_ctx()
if "msgs" not in st.session_state:
    st.session_state.msgs = []
if "opening_done" not in st.session_state:
    st.session_state.opening_done = False
ctx = st.session_state.ctx
ctx["mirror_fn"] = mirror_fn_factory(ctx)
ctx.setdefault("collected", [])
ctx.setdefault("rejected", [])

# ==================================================================
# 侧栏 —— **要短。用户说过侧栏啰嗦，而且不要旁白。**
# ==================================================================
with st.sidebar:
    st.markdown("## 🪞 志业镜 · 对话")
    # 【这行原来写的是「我不替你挑，也不给你打分」——已删】
    # 那道线在代码里守着就够了；挂在嘴上就成了旁白。
    st.caption("陪你聊「以后学什么」。")

    # 【密钥从哪儿读：三种来源，按云上能不能用排序】
    # ① `st.secrets` —— **Streamlit 云上唯一可行的方式**。
    #    云上的容器不给你设环境变量，但 Secrets 面板里的值会进这里。
    #    以前只读 `os.environ`，所以传到云上就是「没填 key」，
    #    整个应用退化成规则模式——**看起来像没配好，其实是读错了地方。**
    # ② 环境变量 —— 本机跑、或者自建服务器（Docker/Zeabur 之类）走这条。
    # ③ 让用户自己填 —— 兜底。访问者自己贴一个 key，只活在这次会话里。
    #
    # 【访问 st.secrets 必须包 try】
    # 没有 secrets 文件时它会**抛异常**（不是返回空），
    # 而本机跑通常就是没有 secrets 文件的。
    key = ""
    try:
        key = st.secrets.get("DEEPSEEK_API_KEY", "") or ""
    except Exception:                       # noqa: BLE001
        key = ""
    if not key:
        key = os.environ.get("DEEPSEEK_API_KEY", "")
    if not key:
        key = st.text_input("DeepSeek API Key", type="password",
                            placeholder="sk-...")

    _n_c = len(ctx.get("collected", []))
    _n_r = len(ctx.get("rejected", []))
    if _n_c or _n_r:
        st.caption(f"收下 {_n_c} · 排除 {_n_r}")

    st.markdown("---")
    if st.button("🔄 重新开始", width="stretch"):
        st.session_state.ctx = new_ctx()
        st.session_state.msgs = []
        st.session_state.opening_done = False
        st.session_state.pop("iv_ui", None)
        st.rerun()

    # 【入口放在侧栏，和「重新开始」同一层】
    # 用户原话：「选择卡片只是形式之一」——翻牌是它问你「要不要」，
    # 访谈是它问你「你是什么样」。这两件事**没有先后**，
    # 所以入口不该藏在流程深处。
    if st.button("🎙 换我问你几个问题", width="stretch", key="iv_enter"):
        st.session_state.iv_ui = {"i": 0, "ans": {}}
        st.rerun()

    # 底细收进折叠里 —— 该说的都说了，但不占版面
    with st.expander("我手上有什么、没有什么"):
        _off = sum(1 for m in MAJORS if m.get("in_official"))
        _sat = sum(1 for m in MAJORS if m.get("chsi_sat"))
        _jy = sum(1 for m in MAJORS if m.get("chsi_jyfx"))
        _dim = sum(1 for m in MAJORS if m.get("dims"))
        _dim_c1 = sum(1 for m in MAJORS if m.get("dims_tier") == "C1")
        _r1 = sum(1 for m in MAJORS if m.get("rating"))
        _r2 = sum(1 for m in MAJORS if m.get("rec_index"))
        _tpl = sum(1 for m in MAJORS if m.get("cost_templated"))
        _cost = sum(1 for m in MAJORS if m.get("cost_hours"))
        _xs = sum(1 for m in MAJORS if m.get("chsi_xsgm"))
        # 【原来这九条是把每张卡下面那份「来源与底细」又抄了一遍】
        # 现在这里只说**库的整体家底**（每条有多少个专业有），
        # 逐条出处由卡下面的那份负责。两边不再互相重复。
        st.markdown(
            f"- 牌堆 `{len(MAJORS)}` / 官方目录 `883` 个专业；"
            f"`分类·代码·学位` **{_off}** 全部对得上（教育部《本科专业目录》）\n"
            f"- `就业方向` **{_jy}**（学职平台）· "
            f"`在校生规模` **{_xs}**、`四维满意度` **{_sat}**（学信网，"
            f"**学生自评，不是就业率**）\n"
            f"- `7 维需求画像` **{_dim}**（**{_dim_c1}** 条有引文）· "
            f"`代价数字` **{_cost}**（**{_tpl}** 条是模板值）\n"
            f"- `三维星级` **{_r1}** / `推荐指数` **{_r2}** —— "
            f"**两位老师各自的判断，不是数据**")
        st.caption("我没有的东西也一并说清楚：**选科要求**（权威源在各省"
                   "考试院）、**薪资数字**（平台上那个「薪酬」是在读学生"
                   "打的分，不是钱）。有牌的专业，卡下面都逐条写着它是"
                   "从哪儿来的。")

# ==================================================================
# 「它反过来问你」——访谈占主区，走完回聊天
# ==================================================================
def interview_ui():
    """七个问题的界面。**判分一律走 `interview_run`，这里不自己算。**

    返回 True 表示这一轮访谈接管了主区。
    """
    iv = st.session_state.get("iv_ui")
    if not iv:
        return False
    QS = interview_questions(DIM_NAMES, ASK, Q_OF)
    st.markdown("### 🎙 换我问你")
    st.caption("七个问题，问的都是**你实际干过什么**——不是让你给自己打分。"
               "**「没试过」也是答案**，点它就完了。")

    done = iv["i"] >= len(QS)
    if not done:
        q = QS[iv["i"]]
        _opts = interview_options_of(q["dimension"], OPTIONS)
        st.markdown(f"**{iv['i'] + 1}/{len(QS)}　{q['question']}**")
        _labels = [t for _s, t in _opts]
        _pick = st.radio("选一个最像你的", _labels, index=None,
                         key=f"iv_pick_{iv['i']}",
                         label_visibility="collapsed")
        _back = st.button("← 先不答了", key="iv_quit")
        if _back:
            st.session_state.pop("iv_ui", None)
            st.rerun()
        if _pick is not None:
            _score, _ = interview_label_of(q["dimension"],
                                           _labels.index(_pick), OPTIONS)
            # 【答案走 interview_run，不自己往 ans 里塞】
            # 它负责三件事：非法分不采信、引文要核得上、
            # 「没试过」记「不知道」而不是低分。自己判分就会重犯那些错。
            interview_submit(run_tool, ctx, q["dimension"], _score, _pick)
            iv["ans"][q["dimension"]] = _score
            iv["i"] += 1
            st.rerun()
        return True

    # ── 走完了：出结果 ──
    _r = interview_finish(run_tool, ctx)
    st.markdown("### 答完了，对一遍")
    for line in interview_result_rows(
            _r["counts"], _r["agree_sample"], _r["gaps"],
            _r["long_list"], DIM_NAMES):
        render_assistant(line)
    if st.button("聊点别的", key="iv_done"):
        st.session_state.pop("iv_ui", None)
        st.rerun()
    return True


if not interview_ui():
    # ==================================================================
    # 对话区
    # ==================================================================
    st.markdown("### 🪞 志业镜 · 对话")

    if not st.session_state.opening_done:
        st.session_state.opening_done = True
        # 【开场白为什么要有好几条，而且每次都换】
        # 原来只有写死的一句：「最近有什么事，是你自己愿意多花点时间的？」
        # 用户的反馈是「每次一开始就是有什么愿意多花时间的，烦不烦啊，
        # 能不能更个性化一点」。
        #
        # 那句话有两个毛病：
        #   ① **它在逼人表态。** 让人先定义自己「愿意为什么花时间」——
        #      很多人答不上来，答不上来不是他的问题。
        #   ② **它把门关窄了。** 它假定来的人已经准备好聊兴趣了。
        #      可来的人可能正担心成绩、怕选错、家里有压力，
        #      或者只是想说说话。这些人看到那句话就退了。
        #
        # 所以改成几条**跨开的路**：有的给事、有的给话、有的根本不问。
        # `st.session_state.greeted_before` 记着上次用的哪条——
        # **同一个人下次进来不会看到同一句。**
        _OPENERS = [
            # ① 【把「我能给你什么」摆出来，让他按自己的需要问】
            # 用户的原话：「比如你说『我有什么能帮到您』，根据用户需要回答」。
            #
            # 【为什么这条放第一位】
            # 它不逼人表态——**它先把自己的能力交出去**，
            # 让用户从自己的需要出发挑。
            # 前面几条（问他在忙什么、问他上周三干嘛）虽然宽松，
            # 但**都是在要他先给东西**；这一条不是。
            #
            # 【但不能写成客服腔】
            # 「我有什么能帮到您」是客服话，念出来像电话客服。
            # 所以把它落成**具体的清单**——说得出我到底能干什么，
            # 而不是空问一句「需要什么帮助」。
            # 清单一具体，用户才知道可以问什么。
            "我先说我这儿有什么，你挑着来。\n\n"
            "我能干这些：\n"
            "- **你说个专业名**，我给你翻张牌——它要什么、累在哪、"
            "毕业往哪走\n"
            "- **你想比比两个**，我把它们放一起对\n"
            "- **你心里有个方向但说不清**，那就聊，聊到能说清为止\n"
            "- **你单纯想找人说说话**，那也行，不聊专业也不冷场\n\n"
            "**你想从哪儿开始？**",

            # ② 不问，只把门开着
            "来了。\n\n"
            "这儿不用先想清楚——**说件具体的事就行**：最近在忙什么、"
            "烦什么、在玩什么。\n\n"
            "你要只是想吐槽两句，也接得住。",

            # ② 给一个「最小的事实」，比问「你喜欢什么」好答得多
            "不用自我介绍，也不用想明白才来。\n\n"
            "先从最小的事说起：**上周三下午你在干嘛？**\n\n"
            "上课、打球、打游戏、睡觉、剪视频——"
            "**你说什么我都不觉得这有什么。**",

            # ③ 承认「不知道」是好答案
            "你先说，或者先别说，都行。\n\n"
            "要是你现在的状态是**「我也不知道我想干嘛」**——"
            "那正好，这话我听得最多，**而且它是好答案**，不是坏答案。\n\n"
            "那换个问法：**你最近一次忘了看时间，是在干嘛？**",

            # ④ 迟到的，有的直接看牌
            "你要是已经有个大概方向——说个词就行，我给你翻张牌看看。\n\n"
            "没有也没关系。**那就从你最近在忙的事说起。**",

            # ⑤ 直接给个能立刻动手的小事
            "不聊大道理，先做件小事也行。\n\n"
            "**拿张纸，写三件你今年做过、当时还挺投入的事。**"
            "写完念给我听，或者直接说。\n\n"
            "不用挑「有意义」的——**越琐碎越好，琐碎的才真。**",
        ]

        _n = len(_OPENERS)

        # 【换一条，不重样——而且这个「不重样」必须跨刷新也成立】
        # 第一版我把「上次用的第几条」存在 `session_state` 里。
        # 那是错的：**浏览器每刷新一次就是一个新会话**，
        # `session_state` 每次都是空的，于是永远停在第 1 条——
        # 「每次换一条」等于没做。
        # 所以改成本地留一个记号文件。
        #
        # 【它是什么，不是什么】
        # 它**不是账号系统**，不记你说过什么，也没有任何身份信息——
        # 只存一个整数：「上次给他看的是第几条开场」。
        # 所以这个文件只有一个数字，读不出来也完全不影响使用。
        # 【为什么不用随机数】随机会重复，而「每次都是这句」
        # 正是用户提的那个问题本身——随机解决不了它。
        # 【为什么不用 `__file__`】
        # 组装出来的应用是被 exec 进一个命名空间跑的，
        # 那时候 `__file__` 可能不存在——`os.path.abspath(__file__)`
        # 会当场 NameError（实测报的就是 `name '__file__' is not defined`）。
        #
        # 【为什么也不能用 `os.getcwd()`】
        # 原来这里写的是 `os.path.join(os.getcwd(), "_开场记号.txt")`。
        # 在我的机器上没问题；**在 Streamlit 云上会炸**——
        # 云上的仓库目录是**只读**的，那句话会 OSError。
        # （外面虽然有个 `except OSError: pass` 兜着不会崩，
        #  但记号永远写不进去，开场白就退化成一条不换的——
        #  **而那正是用户最开始抱怨的那个毛病**。
        #  所以这不是「不崩就行」，这是功能真的没了。）
        #
        # 【改法：找一个真能写的目录】
        # 从临时目录往下试，**真的写一个探针文件**才算数——
        # 不能只看目录存不存在（云上目录存在但不可写）。
        # 都写不进去就**当场随机挑一条**：换着来这个效果还在，
        # 只是下一次不一定跟这一次不同。**宁可随机，也不要每次都第一句。**
        def _writable_dir():
            _cands = [os.path.join(tempfile.gettempdir(), "zhiyejing"),
                      tempfile.gettempdir(), os.getcwd()]
            for _d in _cands:
                try:
                    os.makedirs(_d, exist_ok=True)
                    _probe = os.path.join(_d, ".probe")
                    with open(_probe, "w", encoding="ascii") as _f:
                        _f.write("1")
                    os.remove(_probe)
                    return _d
                except OSError:
                    continue
            return None

        _dir = _writable_dir()
        if _dir is None:
            _i = random.randrange(_n)
            _last = None
        else:
            _MARK = os.path.join(_dir, "_开场记号.txt")
            try:
                with open(_MARK, encoding="ascii") as f:
                    _last = int(f.read().strip())
            except (OSError, ValueError):
                _last = None
            _i = 0 if _last is None else (_last + 1) % _n
            try:
                with open(_MARK, "w", encoding="ascii") as f:
                    f.write(str(_i))
            except OSError:
                pass
        # 回来过的人要说一句，不然「重新开始」看起来像程序重启
        _back = st.session_state.get("greeted_before")
        st.session_state.greeted_before = True
        _head = ("又来了。\n\n" if _back else "")
        st.session_state.msgs.append(
            {"role": "assistant", "text": _head + _OPENERS[_i]})

    for m in st.session_state.msgs:
        with st.chat_message("assistant" if m["role"] == "assistant"
                             else "user"):
            if m["role"] == "assistant":
                render_assistant(m["text"])
            else:
                st.markdown(m["text"])

# ---- 输入 ----
# 【公开部署要有个费用上限】
# 本机跑、自己填 key，随便聊多少轮都无所谓。
# 但**传到 Streamlit 云上公开访问**就是另一回事：
# 密钥如果由我们出，陌生人可以一直刷我们的账单。
# 所以给每个会话一个轮数上限。
#
# 【为什么做成可按环境变量调】
# 我自己演示时想多聊几轮；公开时想收紧。写死一个数两头都不合适。
try:
    _CAP = int(os.environ.get("ZHIYEJING_MAX_TURNS", "30"))
except ValueError:
    _CAP = 30
_turns = st.session_state.get("turns", 0)
_used_up = _turns >= _CAP

user_text = st.chat_input(
    "先说满这段对话了，重开一页可以接着聊"
    if _used_up else
    "说个专业名、问问区别，或者随便说点什么",
    disabled=_used_up)

if user_text and not _used_up:
    st.session_state.turns = _turns + 1
    st.session_state.msgs.append({"role": "user", "text": user_text})
    with st.chat_message("user"):
        st.markdown(user_text)

    with st.chat_message("assistant"):
        if not key:
            # 没 key 时的翻卡模式。**不解释自己，直接给东西。**
            #
            # 【这一段原来只认完整专业名】
            # 原来是一行：
            #     hit = next((mm for nm, mm in BY_NAME.items() if nm in low), None)
            # 要求专业全名**完整出现**在输入里。于是「计算机」「软工」
            # 「我想学医」全接不住——而输入框的提示语承诺的是
            # 「说个专业名、问问区别，或者随便说点什么」。
            # **提示语比这条规则能给的宽得多，人一打就撞墙。**
            # 现在换成 `keyless_reply()`：全名、专业类名、简称、口语、
            # 打错的字都认，认不准就给相近的几张，实在没有才说没有。
            line, cards = keyless_reply(user_text)
            # 【为什么把卡片拼进文本、交给 `render_assistant` 去画】
            # 我第一版是直接 `st.markdown(card_html(_m))` 画的，
            # **结果用户一张卡也看不到**。
            # 原因在下面那句 `st.rerun()`：
            # 它会**丢掉重跑之前刚产生的那一批 delta**。
            # 最小实验（`_审计/_probe_rerun_drops.py`）验过：
            # 同一批里画的普通 markdown 活下来了——因为它被记进历史、
            # 重跑后又被重放了一遍；而那张只画不记的卡片没了。
            # **只画不记 = 白画。**
            # 记成 `[[CARD:名字]]` 之后，重放那一遍由 `render_assistant`
            # 换成卡片——那条路是被重跑调用到的，画得上。
            # 顺带一个好处：没填 key 和有 key 两条路，最终都走同一个渲染器。
            text = line
            for _m in cards:
                text += f"\n\n[[CARD:{_m['n']}]]"
            # 【为什么话要被 `render_assistant` 画两遍也不怕】
            # 重跑时 `msgs` 会被重放，所以下一轮画的是历史里那条；
            # 这一轮画的会被丢掉。两遍的净效果就是一遍。
            st.session_state.msgs.append({"role": "assistant", "text": text})
            render_assistant(text)
        else:
            with st.spinner(""):
                hist = [{"role": ("assistant" if x["role"] == "assistant"
                                  else "user"), "content": x["text"]}
                        for x in st.session_state.msgs[-14:]]
                full = ([{"role": "system", "content": SYSTEM_PROMPT}]
                        + hist)
                ctx["trace"] = []
                text, calls, err = stream_llm(_client(key), full, ctx)

            if err:
                # 【公开部署时，报错要报人话】
                # 云上常见的失败是：密钥额度用尽、被限流、网络抖。
                # 直接甩一句英文栈给访问者，他只会觉得这应用坏了。
                # 但**也不能假装没事**——说清是网络那头的问题，
                # 而且给他一条还能走的路（重开一页、或者用没填 key 的翻卡模式）。
                st.warning("**这轮没接上。**"
                           "多半是网络那头的事，不是你的问题。"
                           "重开一页再试，或者直接打专业名——"
                           "**那个不用联网也能翻卡给你看。**")
                st.session_state.msgs.append(
                    {"role": "assistant",
                     "text": "（这轮没接上，重开一页再试。）"})
                st.caption(f"（技术细节：{err}）")
            else:
                text, why = guard(text, calls, ctx.get("seen_nums"))
                if why:
                    # 丢掉了就说丢掉了，但**不解释机制**，而且
                    # **同一秒把内容补上**——不能只留一句客气话。
                    # 详见 `_angle_shift()` 上面那段注释。
                    _fix = _angle_shift(text)
                    _line = _fix or (
                        "这条我说不准。**不过换个问法还有的聊：**"
                        "你说的这两条，各自要什么、出来往哪走，"
                        "你挑一个先问我，我给你摊开。")
                    st.warning(_line)
                    # 把这一轮记进去，免得上下文错位。
                    # 【删掉了原来那句自我检讨】
                    # 原来是「（刚才那句我说过头了，我自己收回来。）」+ 正文。
                    # 用户原话：「你给我把刚才那句『我说过头了，我自己收回来』
                    # 删掉，我不要你注意了，这部分删掉就好了」。
                    # 对——**自报失误是把注意力引到机制上**，
                    # 而他要的是内容。所以只留正文。
                    st.session_state.msgs.append(
                        {"role": "assistant", "text": _line})
                else:
                    render_assistant(text)
                    st.session_state.msgs.append(
                        {"role": "assistant", "text": text})
    st.rerun()

# 【用满了要说一句，不能只是让输入框悄悄变灰】
# 输入框把自己禁用了，但**为什么不给用**得说出来，
# 而且要给一条出路——不然用户以为应用坏了。
if _used_up:
    st.info(f"这一段聊了 **{_CAP}** 轮，先到这儿。"
            "**重开一页就能接着聊**——每个新页面都是一段新的对话。")
